use std::{collections::BTreeMap, sync::Arc};
use symbolica::prelude::*;
use symbolica_amflow::{transport_cache::*, *};
fn main() -> Result<()> {
 let started=std::time::Instant::now();
 let (x,y,eps)=symbol!("generic_multimass::x","generic_multimass::y","generic_multimass::eps");
 let family=IntegralFamily{name:"generic_unequal_sunset".into(),loops:vec!["l1".into(),"l2".into()],external:vec![],external_gram:vec![],propagators:vec![Propagator::quadratic(&[1,0],&[],Atom::var(x),&[])?,Propagator::quadratic(&[0,1],&[],Atom::var(y),&[])?,Propagator::quadratic(&[1,-1],&[],Atom::new(),&[])?],physical_propagators:3,epsilon:eps,dimension:4};
 let context=RunContext{progress:Some(Arc::new(|e|if matches!(e,Progress::Prepared{..}|Progress::Sample{..}){eprintln!("{e:?}");})),..Default::default()};
 let options=FlowOptions::default();let backend=RustRedBackend::default();
 let targets=[Integral(vec![1,1,1]),Integral(vec![2,1,1])];
 let prepared=PreparedPhysicalFamily::new(&family,&targets,&[x,y],&backend,&options,"positive unequal vacuum masses",&context)?;
 eprintln!("physical preparation completed in {:?}, {} masters: {:?}",started.elapsed(),prepared.basis().len(),prepared.basis());
 let mut cache=RustFlowCache::default();
 let source=BTreeMap::from([(x,Atom::one()),(y,Atom::num(2))]);
 let destination=BTreeMap::from([(x,Atom::num(Rational::from((3,2)))),(y,Atom::num(Rational::from((5,2))))]);
 let range=EpsilonRange::new(-4,0)?;
 let required=prepared.required_master_range(&destination,range)?;
 let seed=prepared.seed_cache(&mut cache,&source,required.last,16,&options,&backend,&context)?;
 eprintln!("automatic seed completed in {:?}, {} verified digits",started.elapsed(),seed.accuracy.verified_digits());
 let policy=ScaledDistance{scales:BTreeMap::new(),admissible:|_:&CachedBoundary,_:&CachedPoint|Ok(true)};
 let checked=FlowOptions{digits:28,..options.clone()};
 let result=prepared.flow().evaluate_to(&mut cache,&destination,seed.range,&checked,&context,&policy)?;
 let projected=prepared.project_targets(&result.boundary,range,20)?;
 eprintln!("transport completed in {:?}, {} cache entries",started.elapsed(),cache.len());
 let point=KinematicPoint(destination.into_iter().map(|(k,v)|(Atom::var(k),v)).collect());
 let direct=solve_integrals(&family,&targets,&point,0,&options,&backend,&context)?;
 let p=Precision::decimal(80)?;
 for (i,(a,b)) in projected.iter().zip(&direct).enumerate(){for (power,value) in &a.coefficients {let independent=&b.coefficients[power]; if !p.close(value,independent,20){return Err(Error::Accuracy(format!("target {i}, epsilon^{power}: {value} != {independent}")));} println!("target {i} epsilon^{power} transported={value} direct={independent}");}}
 println!("PASSED connected two-loop unequal-mass AMF seed/physical transport/direct AMF; elapsed {:?}; masters {}; bank {}",started.elapsed(),prepared.basis().len(),cache.len());Ok(())
}

